1	package server
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"errors"
7		"sort"
8		"sync"
9		"time"
10	)
11	
12	// Lease operation outcomes surfaced to the HTTP layer.
13	var (
14		errNotFound      = errors.New("instance not found")
15		errLeaseConflict = errors.New("lease conflict")
16	)
17	
18	// instance is one registered service instance plus its lease state. The
19	// exported fields are set once at registration; token and expiresAt are
20	// mutated under the registry lock.
21	type instance struct {
22		Service    string
23		Instance   string
24		Endpoint   string
25		Version    string
26		Zone       string
27		Weight     int
28		TTLSeconds int
29		Metadata   map[string]string
30	
31		token     string
32		expiresAt time.Time
33	}
34	
35	func (i *instance) live(now time.Time) bool { return now.Before(i.expiresAt) }
36	
37	// registry holds all live and expired-but-unpurged instances. Expiration is
38	// evaluated lazily against the caller's clock, so an expired instance can
39	// never reappear in snapshots or be revived by a stale lease token.
40	type registry struct {
41		mu        sync.Mutex
42		instances map[string]map[string]*instance // service -> instance name -> record
43	}
44	
45	func newRegistry() *registry {
46		return &registry{instances: make(map[string]map[string]*instance)}
47	}
48	
49	func newLeaseToken() string {
50		var b [16]byte
51		if _, err := rand.Read(b[:]); err != nil {
52			panic(err)
53		}
54		return hex.EncodeToString(b[:])
55	}
56	
57	// register inserts inst, replacing any previous record with the same name and
58	// minting a fresh lease token (the old token stops matching immediately). It
59	// returns a copy of the stored record and whether a live instance was
60	// overwritten.
61	func (r *registry) register(inst *instance, now time.Time) (instance, bool) {
62		r.mu.Lock()
63		defer r.mu.Unlock()
64		inst.token = newLeaseToken()
65		inst.expiresAt = now.Add(time.Duration(inst.TTLSeconds) * time.Second)
66		byName, ok := r.instances[inst.Service]
67		if !ok {
68			byName = make(map[string]*instance)
69			r.instances[inst.Service] = byName
70		}
71		overwritten := false
72		if prev, ok := byName[inst.Instance]; ok && prev.live(now) {
73			overwritten = true
74		}
75		byName[inst.Instance] = inst
76		return *inst, overwritten
77	}
78	
79	// renew extends the lease of a live instance whose current token matches.
80	func (r *registry) renew(service, name, token string, now time.Time) error {
81		r.mu.Lock()
82		defer r.mu.Unlock()
83		inst := r.lookupLocked(service, name, now)
84		if inst == nil {
85			return errNotFound
86		}
87		if token == "" || token != inst.token {
88			return errLeaseConflict
89		}
90		inst.expiresAt = now.Add(time.Duration(inst.TTLSeconds) * time.Second)
91		return nil
92	}
93	
94	// deregister removes a live instance whose current token matches.
95	func (r *registry) deregister(service, name, token string, now time.Time) error {
96		r.mu.Lock()
97		defer r.mu.Unlock()
98		inst := r.lookupLocked(service, name, now)
99		if inst == nil {
100			return errNotFound
101		}
102		if token == "" || token != inst.token {
103			return errLeaseConflict
104		}
105		delete(r.instances[service], name)
106		if len(r.instances[service]) == 0 {
107			delete(r.instances, service)
108		}
109		return nil
110	}
111	
112	// lookupLocked returns the live record or nil; expired records are treated as
113	// absent. Callers must hold r.mu.
114	func (r *registry) lookupLocked(service, name string, now time.Time) *instance {
115		inst := r.instances[service][name]
116		if inst == nil || !inst.live(now) {
117			return nil
118		}
119		return inst
120	}
121	
122	// snapshot returns copies of the live instances of service matching the
123	// version/zone filters (empty string disables a filter), sorted by instance
124	// name. Copies are taken under the lock so callers can read them race-free.
125	func (r *registry) snapshot(service, version, zone string, now time.Time) []instance {
126		r.mu.Lock()
