298			{"weight zero", "PUT", "/v1/services/svc/instances/i1", registerBody("http://a:1", "v1", "z1", 0, 30)},
299			{"weight too big", "PUT", "/v1/services/svc/instances/i1", registerBody("http://a:1", "v1", "z1", 101, 30)},
300			{"ttl zero", "PUT", "/v1/services/svc/instances/i1", registerBody("http://a:1", "v1", "z1", 10, 0)},
301			{"ttl too big", "PUT", "/v1/services/svc/instances/i1", registerBody("http://a:1", "v1", "z1", 10, 301)},
302			{"malformed JSON", "PUT", "/v1/services/svc/instances/i1", `{"endpoint":`},
303			{"empty body", "PUT", "/v1/services/svc/instances/i1", ``},
