306			{"fractional weight", "PUT", "/v1/services/svc/instances/i1", `{"endpoint":"http://a:1","version":"v1","zone":"z1","weight":10.5,"ttlSeconds":30}`},
307			{"empty metadata key", "PUT", "/v1/services/svc/instances/i1", `{"endpoint":"http://a:1","version":"v1","zone":"z1","weight":10,"ttlSeconds":30,"metadata":{"":"x"}}`},
308			{"empty metadata value", "PUT", "/v1/services/svc/instances/i1", `{"endpoint":"http://a:1","version":"v1","zone":"z1","weight":10,"ttlSeconds":30,"metadata":{"k":""}}`},
309			{"non-string metadata", "PUT", "/v1/services/svc/instances/i1", `{"endpoint":"http://a:1","version":"v1","zone":"z1","weight":10,"ttlSeconds":30,"metadata":{"k":1}}`},
310			{"heartbeat bad name", "POST", "/v1/services/svc/instances/bad!/heartbeat", ""},
311			{"discovery bad name", "GET", "/v1/discovery/bad%20name", ""},
312			{"discovery unknown query", "GET", "/v1/discovery/svc?foo=bar", ""},
313			{"discovery empty version", "GET", "/v1/discovery/svc?version=", ""},
314			{"discovery duplicate query", "GET", "/v1/discovery/svc?zone=z1&zone=z2", ""},
315			{"discovery malformed query", "GET", "/v1/discovery/svc?version=%zz", ""},
316		}
317		for _, tc := range cases {
