	if r.Endpoint == "" || r.Version == "" || r.Zone == "" {
		return false
	}
	if r.Weight < 1 || r.Weight > 100 || r.TTLSeconds < 1 || r.TTLSeconds > 300 {
		return false
	}
	for k, v := range r.Metadata {
		if k == "" || v == "" {
			return false
		}
