127	func (s *server) register(w http.ResponseWriter, r *http.Request) {
128		service, name := r.PathValue("service"), r.PathValue("instance")
129		if !validName(service) || !validName(name) {
130			writeError(w, http.StatusBadRequest, "validation_error")
131			return
132		}
133		var req registerRequest
134		dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
135		dec.DisallowUnknownFields()
136		if err := dec.Decode(&req); err != nil || dec.Decode(&struct{}{}) != io.EOF || !req.valid() ||
137			(req.HealthPolicy != nil && !req.HealthPolicy.valid()) {
138			writeError(w, http.StatusBadRequest, "validation_error")
139			return
140		}
141		metadata := make(map[string]string, len(req.Metadata))
142		for k, v := range req.Metadata {
143			metadata[k] = v
144		}
145		inst := &instance{
146			Service:    service,
147			Instance:   name,
148			Endpoint:   req.Endpoint,
149			Version:    req.Version,
150			Zone:       req.Zone,
151			Weight:     req.Weight,
152			TTLSeconds: req.TTLSeconds,
153			Metadata:   metadata,
154		}
155		var policy healthPolicy
156		if req.HealthPolicy != nil {
157			policy = healthPolicy{
158				FailureThreshold: req.HealthPolicy.FailureThreshold,
159				SuccessThreshold: req.HealthPolicy.SuccessThreshold,
160			}
161		}
162		stored, overwritten := s.registry.register(inst, policy, s.now())
163		status := http.StatusCreated
164		if overwritten {
165			status = http.StatusOK
166		}
167		writeJSON(w, status, registerResponse{instanceView: viewOf(stored), LeaseToken: stored.token})
168	}
